# For each region, find the bounding box of non-background (non-8) data
def find_region_bounds(grid, row_start, row_end, col_start, col_end):
    """Find bounds of non-8 values in a region"""
    min_row, max_row = row_start, row_end
    min_col, max_col = col_start, col_end

    for r in range(row_start, row_end + 1):
        for c in range(col_start, col_end + 1):
            if grid[r][c] != 8:
                min_row = min(min_row, r)
                max_row = max(max_row, r)
                min_col = min(min_col, c)
                max_col = max(max_col, c)

    return (min_row, max_row, min_col, max_col)

